spec.query:
from(bucket: "nas")
  |> range(start: v.timeRangeStart, stop:v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "node_boot_time_seconds")
  |> last()
  |> map(fn: (r) => ({
      r with
      _value: float(v: int(v: now()) / 1000000000) - r._value
  }))

from(bucket: "proxmox")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) =>
    r._measurement == "cpustat" and
    r._field == "cpu" and
    r.host != "offsite-backup"
  )
  |> group(columns: ["host"])
  |> aggregateWindow(
    every: v.windowPeriod,
    fn: mean,
    createEmpty: false
  )

from(bucket: "offsite-backup")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) =>
    r._measurement == "smartctl_device_smart_status"
  )
  |> aggregateWindow(every: v.windowPeriod, fn: last)

from(bucket: "nas")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) =>
    r._measurement == "smartctl_device_smart_status"
  )
  |> aggregateWindow(every: v.windowPeriod, fn: last)
